169	
170	// Local IP of your PC running the Backend (port 8080)
171	const char* BACKEND_HOST  = "http://192.168.1.50:8080"; 
172	
173	const int BTN_NEXT_PIN     = 18; // Button to cycle between the 3 tasks
174	const int BTN_COMPLETE_PIN = 19; // Button to mark selected task as DONE
175	
176	struct FocusTask {
177	  String id;
178	  String title;
179	  String listTitle;
