181	};
182	
183	FocusTask triplet[3];
184	int tripletCount = 0;
185	int selectedIndex = 0; // 0, 1, or 2
186	
187	// =============================================================================
188	// API CLIENT FUNCTIONS
189	// =============================================================================
190	
191	// 1. Fetch Top 3 Tasks from Backend
192	bool fetchTripletQueue() {
193	  if (WiFi.status() != WL_CONNECTED) return false;
194	
195	  HTTPClient http;
196	  String url = String(BACKEND_HOST) + "/api/v1/golden-hour/esp32/queue?limit=3";
197	  http.begin(url);
198	
199	  int httpCode = http.GET();
200	  if (httpCode == 200) {
201	    String payload = http.getString();
202	    
203	    StaticJsonDocument<1024> doc;
204	    DeserializationError error = deserializeJson(doc, payload);
205	    if (!error) {
206	      JsonArray taskArray = doc["tasks"].as<JsonArray>();
207	      tripletCount = 0;
208	
209	      Serial.println("========================================");
210	      Serial.println("[ESP32 TRIPLET FOCUS QUEUE]");
211	      for (JsonObject t : taskArray) {
212	        if (tripletCount < 3) {
213	          triplet[tripletCount].id        = t["task_id"].as<String>();
214	          triplet[tripletCount].title     = t["title"].as<String>();
215	          triplet[tripletCount].listTitle = t["tasklist_title"].as<String>();
216	          triplet[tripletCount].index     = t["index"].as<int>();
217	
218	          Serial.printf(" [%d] %s (%s)\n", 
219	            triplet[tripletCount].index, 
220	            triplet[tripletCount].title.c_str(), 
221	            triplet[tripletCount].listTitle.c_str()
222	          );
223	          tripletCount++;
224	        }
225	      }
226	      Serial.printf("Total remaining in queue: %d\n", doc["total_in_queue"].as<int>());
227	      Serial.println("========================================");
228	
229	      selectedIndex = 0; // Focus on top task by default
230	      http.end();
231	      return true;
232	    }
233	  }
234	  http.end();
235	  return false;
236	}
237	
238	// 2. Mark Selected Task as Completed (Instant < 2ms response)
239	bool completeSelectedTask() {
240	  if (WiFi.status() != WL_CONNECTED || tripletCount == 0) return false;
241	
242	  HTTPClient http;
243	  String url = String(BACKEND_HOST) + "/api/v1/golden-hour/google-tasks/complete";
244	  http.begin(url);
245	  http.addHeader("Content-Type", "application/json");
246	
247	  StaticJsonDocument<256> doc;
248	  doc["task_id"] = triplet[selectedIndex].id;
249	
250	  String requestBody;
251	  serializeJson(doc, requestBody);
252	
253	  int httpCode = http.POST(requestBody);
254	  if (httpCode == 200) {
255	    Serial.println("========================================");
256	    Serial.printf("[TASK COMPLETED] %s\n", triplet[selectedIndex].title.c_str());
257	    Serial.println("Local cache updated (<2ms). Synced to Google.");
258	    Serial.println("========================================");
259	    http.end();
260	    
261	    // Automatically pull the fresh triplet queue
262	    fetchTripletQueue();
263	    return true;
264	  }
265	  http.end();
