272	void setup() {
273	  Serial.begin(115200);
274	  pinMode(BTN_NEXT_PIN, INPUT_PULLUP);
275	  pinMode(BTN_COMPLETE_PIN, INPUT_PULLUP);
276	
277	  Serial.println("\n[ESP32] Connecting to Wi-Fi...");
278	  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
