282	  }
283	  Serial.println("\n[ESP32] Wi-Fi Connected! IP: " + WiFi.localIP().toString());
284	
285	  // Fetch initial triplet
286	  fetchTripletQueue();
287	}
288	
289	void loop() {
290	  // 1. Cycle between the 3 tasks
291	  if (digitalRead(BTN_NEXT_PIN) == LOW) {
292	    delay(50); // Debounce
293	    if (digitalRead(BTN_NEXT_PIN) == LOW && tripletCount > 0) {
294	      selectedIndex = (selectedIndex + 1) % tripletCount;
295	      Serial.printf("[ESP32] Focus Shifted -> [%d] %s\n", 
296	        triplet[selectedIndex].index, 
297	        triplet[selectedIndex].title.c_str()
298	      );
