136	// 6. LOW-POWER ROUTINES (METHOD B: HARD POWER-DOWN & PARASITIC PREVENTION)
137	// ============================================================================
138	
139	void powerDownRfidHardware() {
140	    if (rfidHardSleeping) return;
141	
142	    Serial.println(F("[POWER_OPT] Forcing MFRC522 into 0.2 µA Hard Power-Down..."));
143	
144	    // Step 1: Turn off internal RF transmitter
145	    rfid.PCD_AntennaOff();
146	
147	    // Step 2: Drive RST LOW (Enters Hard Power Down Mode on NXP Silicon)
148	    digitalWrite(PIN_RFID_RST, LOW);
149	
150	    // Step 3: Anti-Parasitic Leakage: Set SPI pins to LOW to prevent phantom powering via ESD diodes
151	    digitalWrite(PIN_RFID_SS, LOW);
152	    digitalWrite(PIN_RFID_MOSI, LOW);
153	    digitalWrite(PIN_RFID_SCK, LOW);
154	
155	    rfidHardSleeping = true;
156	    Serial.println(F("[POWER_OPT] MFRC522 RF oscillator killed. Zero RF emission active."));
157	}
158	
159	void wakeUpRfidHardware() {
160	    if (!rfidHardSleeping) return;
161	
162	    Serial.println(F("[POWER_OPT] Waking MFRC522 from Hard Power-Down..."));
163	
164	    // Step 1: Exit Hard Power-Down
165	    digitalWrite(PIN_RFID_RST, HIGH);
166	    delay(25); // Allow crystal oscillator to stabilize
167	
168	    // Step 2: Re-initialize VSPI Bus
169	    digitalWrite(PIN_RFID_SS, HIGH);
170	    SPI.begin(PIN_RFID_SCK, PIN_RFID_MISO, PIN_RFID_MOSI, PIN_RFID_SS);
171	
172	    // Step 3: Re-initialize MFRC522 registers and antenna
173	    rfid.PCD_Init();
174	    delay(10);
175	    rfid.PCD_SetAntennaGain(MFRC522::RxGain_max);
176	    rfid.PCD_AntennaOn();
177	
178	    // Re-load default Key A
179	    for (byte i = 0; i < 6; i++) {
180	        key.keyByte[i] = 0xFF;
181	    }
182	
183	    rfidHardSleeping = false;
184	    Serial.println(F("[POWER_OPT] MFRC522 is ONLINE & antenna energized for card scan."));
185	}
