191	void initFlashStorage() {
192	    if (!LittleFS.begin()) {
193	        Serial.println(F("[STORAGE] LittleFS mount failed!"));
194	        return;
195	    }
196	    Serial.println(F("[STORAGE] LittleFS mounted successfully."));
197	
198	    // Create log file if it doesn't exist
199	    if (!LittleFS.exists(LOG_FILE_PATH)) {
200	        File logFile = LittleFS.open(LOG_FILE_PATH, "w");
201	        if (logFile) {
202	            logFile.print("[]");
203	            logFile.close();
204	            Serial.println(F("[STORAGE] Created new log file."));
205	        }
206	    }
207	}
