209	void logEntryToFlash(const String& uid, uint32_t timestamp) {
210	    File logFile = LittleFS.open(LOG_FILE_PATH, "r");
211	    if (!logFile) {
212	        Serial.println(F("[STORAGE] Error opening log for read."));
213	        return;
214	    }
215	
216	    // Read existing entries
217	    StaticJsonDocument<8192> doc;
218	    DeserializationError error = deserializeJson(doc, logFile);
219	    logFile.close();
220	
221	    if (error) {
222	        Serial.printf("[STORAGE] JSON parse error: %s\n", error.c_str());
223	        return;
224	    }
225	
226	    // Check if array, if not create one
227	    if (!doc.is<JsonArray>()) {
228	        doc.clear();
229	        doc = JsonArray();
230	    }
231	
232	    // Trim to max entries if needed
233	    JsonArray entries = doc.as<JsonArray>();
234	    while (entries.size() >= MAX_LOG_ENTRIES) {
235	        entries.remove(0);
236	    }
237	
238	    // Create new entry
239	    JsonObject newEntry = entries.createNestedObject();
240	    newEntry["uid"] = uid;
241	    newEntry["timestamp"] = timestamp;
242	    newEntry["status"] = "completed";
243	
244	    // Write back
245	    logFile = LittleFS.open(LOG_FILE_PATH, "w");
246	    if (logFile) {
247	        serializeJson(doc, logFile);
248	        logFile.close();
249	        Serial.printf("[STORAGE] Logged entry: UID=%s @ %u\n", uid.c_str(), timestamp);
250	    }
251	}
