253	void readLogFromFlash() {
254	    File logFile = LittleFS.open(LOG_FILE_PATH, "r");
255	    if (!logFile) {
256	        Serial.println(F("[STORAGE] Error opening log for read."));
257	        return;
258	    }
259	
260	    StaticJsonDocument<8192> doc;
261	    DeserializationError error = deserializeJson(doc, logFile);
262	    logFile.close();
263	
264	    if (error) {
265	        Serial.printf("[STORAGE] JSON parse error: %s\n", error.c_str());
266	        return;
267	    }
268	
269	    if (!doc.is<JsonArray>()) {
270	        Serial.println(F("[STORAGE] Log is empty or malformed."));
271	        return;
272	    }
273	
274	    JsonArray entries = doc.as<JsonArray>();
275	    Serial.printf("[STORAGE] Total entries in log: %u\n", entries.size());
276	
277	    for (size_t i = 0; i < entries.size() && i < 10; i++) {
278	        JsonObject entry = entries[i];
279	        Serial.printf("  [%u] UID=%s @ %u (status: %s)\n",
280	                      i,
281	                      entry["uid"].as<const char*>(),
282	                      entry["timestamp"].as<uint32_t>(),
283	                      entry["status"].as<const char*>());
284	    }
285	
286	    if (entries.size() > 10) {
287	        Serial.printf("  ... and %u more entries\n", entries.size() - 10);
288	    }
289	}
