294	void setup() {
295	    // 1. CPU DYNAMIC POWER SCALING: Drop from 240MHz to 80MHz (60% power reduction)
296	    setCpuFrequencyMhz(80);
297	
298	    Serial.begin(115200);
299	    delay(200);
300	
301	    Serial.println();
302	    Serial.println(F("**************************************************"));
303	    Serial.println(F("*  VGWD025K3 ~ CODEX OF TIME (LOCAL-ONLY MVP)   *"));
304	    Serial.println(F("*  Varis Gear Chrono Actuator | ESP32-WROOM-32  *"));
305	    Serial.println(F("**************************************************"));
306	
307	    // 2. HARDWARE POWER SAVING: Kill Wi-Fi and Bluetooth controllers
308	    WiFi.mode(WIFI_OFF);
309	    btStop();
310	    esp_bt_controller_disable();
311	    Serial.printf("[POWER_OPT] CPU Clock: %d MHz | Wi-Fi: OFF | Bluetooth: OFF\n", getCpuFrequencyMhz());
312	
313	    // 3. Initialize Flash Storage
314	    initFlashStorage();
315	
316	    // Pin Modes
317	    pinMode(PIN_TFT_CS, OUTPUT);
318	    pinMode(PIN_RFID_SS, OUTPUT);
319	    pinMode(PIN_RFID_RST, OUTPUT);
320	    pinMode(PIN_RFID_MOSI, OUTPUT);
321	    pinMode(PIN_RFID_SCK, OUTPUT);
322	
323	    digitalWrite(PIN_TFT_CS, HIGH);
324	    digitalWrite(PIN_RFID_SS, HIGH);
325	
326	    // 4. Initialize JQ8900 Audio Player on GPIO 33
327	    Serial.printf("[AUDIO] Initializing JQ8900 Audio Driver on GPIO %d (Serial2 @ 9600)...\n", PIN_AUDIO_TX);
328	    audio.begin(PIN_AUDIO_TX, -1, 9600);
329	    delay(100);
330	    audio.setVolume(AUDIO_DEFAULT_VOL);
331	
332	    // 5. Start HSPI for GC9A01 Display (GPIO 15 Clock, GPIO 2 Data)
333	    hspi.begin(PIN_LCD_SCK, -1, PIN_LCD_MOSI, PIN_TFT_CS);
334	    tft.begin();
335	    tft.setRotation(2); // Inverted 180° orientation
336	    tft.fillScreen(COLOR_BG);
337	
338	    // 6. Start VSPI for MFRC522 RFID
339	    digitalWrite(PIN_RFID_RST, HIGH);
340	    delay(30);
341	    SPI.begin(PIN_RFID_SCK, PIN_RFID_MISO, PIN_RFID_MOSI, PIN_RFID_SS);
342	    rfid.PCD_Init();
343	    delay(20);
344	    rfid.PCD_SetAntennaGain(MFRC522::RxGain_max);
345	    rfid.PCD_AntennaOn();
346	
347	    for (byte i = 0; i < 6; i++) {
348	        key.keyByte[i] = 0xFF;
349	    }
350	    rfidHardSleeping = false;
351	
352	    // Enter Standby State
353	    transitionToState(STATE_IDLE_READY);
354	    Serial.println(F("[SYSTEM] Codex of Time Ready. Standby waiting for card.\n"));
355	}
