357	// ============================================================================
358	// 9. MAIN RUNTIME LOOP
359	// ============================================================================
360	void loop() {
361	    uint32_t currentMillis = millis();
362	
363	    // 1. Process Debug / Command Input via Serial
364	    handleSerialCommands();
365	
366	    // 2. State Machine Dispatcher
367	    switch (currentState) {
368	        case STATE_IDLE_READY: {
369	            // Periodic Non-blocking RFID Polling (every 100ms in standby)
370	            if (currentMillis - lastRfidPollMillis >= 100) {
371	                lastRfidPollMillis = currentMillis;
372	
373	                // Look for new card
374	                if (rfid.PICC_IsNewCardPresent() && rfid.PICC_ReadCardSerial()) {
375	                    currentCardUID = "";
376	                    for (byte i = 0; i < rfid.uid.size; i++) {
377	                        if (rfid.uid.uidByte[i] < 0x10) currentCardUID += "0";
378	                        currentCardUID += String(rfid.uid.uidByte[i], HEX);
379	                        if (i < rfid.uid.size - 1) currentCardUID += ":";
380	                    }
381	                    currentCardUID.toUpperCase();
382	
383	                    MFRC522::PICC_Type piccType = rfid.PICC_GetType(rfid.uid.sak);
384	                    Serial.println(F("--------------------------------------------------"));
385	                    Serial.printf("[CARD DETECTED]\n");
386	                    Serial.printf("  ├─ UID String : %s\n", currentCardUID.c_str());
387	                    Serial.printf("  ├─ SAK Byte   : 0x%02X\n", rfid.uid.sak);
388	                    Serial.printf("  └─ Card Type  : %s\n", rfid.PICC_GetTypeName(piccType));
389	                    Serial.println(F("--------------------------------------------------"));
390	
391	                    // Halt card immediately (no writes)
392	                    rfid.PICC_HaltA();
393	                    rfid.PCD_StopCrypto1();
394	
395	                    // Capture timestamp and transition
396	                    sessionStartTime = (uint32_t)(millis() / 1000);
397	                    transitionToState(STATE_CARD_DETECTED);
398	                }
399	            }
400	            break;
401	        }
402	
403	        case STATE_CARD_DETECTED: {
404	            // Log entry to flash immediately
405	            logEntryToFlash(currentCardUID, sessionStartTime);
406	
407	            // Start timer
408	            timerStartMillis = millis();
409	            lastSecondsRemaining = 0xFFFFFFFF;
410	            transitionToState(STATE_TIMER_RUNNING);
411	            break;
412	        }
413	
414	        case STATE_TIMER_RUNNING: {
415	            // ZERO RFID POLLING (MFRC522 in 0.2 µA Hard Power Down)
416	            uint32_t elapsedSec = (currentMillis - timerStartMillis) / 1000;
417	            if (elapsedSec >= timerDurationSeconds) {
418	                Serial.println(F("\n[TIMER] Countdown expired! Session Completed."));
419	                transitionToState(STATE_TIMER_FINISHED);
420	            } else {
421	                uint32_t remainingSec = timerDurationSeconds - elapsedSec;
422	                if (remainingSec != lastSecondsRemaining) {
423	                    lastSecondsRemaining = remainingSec;
424	                    drawTimerRunningScreen(remainingSec);
425	
426	                    if (remainingSec % 60 == 0) {
427	                        Serial.printf("[TIMER RUNNING] Remaining: %02u:%02u | Elapsed: %u s\n",
428	                                      remainingSec / 60, remainingSec % 60, elapsedSec);
429	                    }
430	                }
431	            }
432	            break;
433	        }
434	
435	        case STATE_TIMER_FINISHED: {
436	            // Display completion for 10 seconds then return to Standby
437	            if (currentMillis - stateEntryMillis > 10000) {
438	                Serial.println(F("[SYSTEM] Returning to Standby mode."));
439	                transitionToState(STATE_IDLE_READY);
440	            }
441	            break;
442	        }
443	
444	        case STATE_ERROR: {
445	            if (currentMillis - stateEntryMillis > 3500) {
446	                Serial.println(F("[SYSTEM] Clearing error state. Returning to Standby."));
447	                transitionToState(STATE_IDLE_READY);
448	            }
449	            break;
450	        }
451	    }
452	
453	    // Power-friendly task pacing (prevents CPU 100% busy-loop thrashing)
454	    delay(30);
455	}
