457	// ============================================================================
458	// 10. STATE TRANSITION CONTROLLER (METHOD B POWER & AUDIO HOOKS)
459	// ============================================================================
460	void transitionToState(SystemState newState) {
461	    currentState = newState;
462	    stateEntryMillis = millis();
463	
464	    switch (currentState) {
465	        case STATE_IDLE_READY:
466	            // WAKE UP RFID: Exit Hard Power-Down & re-energize antenna for next card
467	            wakeUpRfidHardware();
468	            drawIdleScreen();
469	            break;
470	
471	        case STATE_CARD_DETECTED:
472	            drawCardDetectedScreen();
473	            break;
474	
475	        case STATE_TIMER_RUNNING:
476	            // METHOD B POWER SAVING: Force Hard Power-Down on MFRC522 via RST clamp
477	            powerDownRfidHardware();
478	
479	            drawTimerRunningScreen(timerDurationSeconds, true);
480	            // TRIGGER AUDIO: Track 2 played ONCE on timer start
481	            Serial.printf("[AUDIO] Triggering Track %d (Timer Start Chime)...\n", TRACK_TIMER_START);
482	            audio.playTrack(TRACK_TIMER_START);
483	            break;
484	
485	        case STATE_TIMER_FINISHED:
486	            drawTimerFinishedScreen();
487	            // TRIGGER AUDIO: Track 7 played ONCE on countdown completion
488	            Serial.printf("[AUDIO] Triggering Track %d (Timer Finished Melody)...\n", TRACK_TIMER_FINISHED);
489	            audio.playTrack(TRACK_TIMER_FINISHED);
490	            break;
491	
492	        case STATE_ERROR:
493	            break;
494	    }
495	}
