501	void drawProgressArc(float progressRatio, uint16_t color) {
502	    const int radius = 112;
503	    const int numTicks = 60;
504	    int activeTicks = (int)(progressRatio * numTicks);
505	
506	    for (int i = 0; i < numTicks; i++) {
507	        float angle = (i * (360.0 / numTicks) - 90.0) * DEG_TO_RAD;
508	        int x1 = TFT_CENTER_X + cos(angle) * (radius - 5);
509	        int y1 = TFT_CENTER_Y + sin(angle) * (radius - 5);
510	        int x2 = TFT_CENTER_X + cos(angle) * radius;
511	        int y2 = TFT_CENTER_Y + sin(angle) * radius;
512	
513	        uint16_t tickColor = (i <= activeTicks) ? color : COLOR_HUD_RING;
514	        tft.drawLine(x1, y1, x2, y2, tickColor);
515	    }
516	}
