589	        tft.setTextColor(COLOR_CYAN_GLOW);
590	        tft.setCursor(85, 60);
591	        tft.print(F("TIMER ACTIVE"));
592	
593	        tft.setTextColor(COLOR_TEXT_MUTED);
594	        tft.setCursor(50, 185);
595	        tft.printf("CARD: %s", currentCardUID.c_str());
596	    }
597	
598	    float progress = 1.0f - ((float)remainingSeconds / (float)timerDurationSeconds);
599	    drawProgressArc(progress, COLOR_CYAN_GLOW);
600	
601	    tft.fillRect(40, 95, 160, 48, COLOR_BG);
602	
603	    uint32_t mins = remainingSeconds / 60;
604	    uint32_t secs = remainingSeconds % 60;
605	    char timeStr[16];
606	    snprintf(timeStr, sizeof(timeStr), "%02u:%02u", mins, secs);
607	
608	    tft.setTextSize(4);
609	    tft.setTextColor(COLOR_TEXT_WHITE);
610	    tft.setCursor(60, 105);
611	    tft.print(timeStr);
612	}
613	
614	void drawTimerFinishedScreen() {
615	    tft.fillScreen(COLOR_BG);
616	
617	    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 115, COLOR_EMERALD);
618	    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 112, COLOR_GOLD);
619	
620	    tft.setTextSize(1);
621	    tft.setTextColor(COLOR_GOLD);
622	    tft.setCursor(68, 55);
623	    tft.print(F("VARIS GEAR VGWD"));
624	
625	    tft.setTextSize(3);
626	    tft.setTextColor(COLOR_EMERALD);
627	    tft.setCursor(48, 100);
628	    tft.print(F("FINISHED"));
629	
630	    tft.setTextSize(1);
631	    tft.setTextColor(COLOR_TEXT_WHITE);
632	    tft.setCursor(65, 150);
633	    tft.print(F("SESSION COMPLETED"));
634	
635	    tft.setTextColor(COLOR_CYAN_GLOW);
636	    tft.setCursor(55, 170);
637	    tft.print(F("LOGGED TO DEVICE"));
638	}
639	
640	void drawErrorScreen(const char* errorMsg) {
641	    tft.fillScreen(COLOR_BG);
642	
643	    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 115, COLOR_CRIMSON);
644	    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 112, COLOR_CRIMSON);
645	
646	    tft.setTextSize(2);
647	    tft.setTextColor(COLOR_CRIMSON);
648	    tft.setCursor(85, 80);
649	    tft.print(F("ERROR"));
650	
651	    tft.setTextSize(1);
652	    tft.setTextColor(COLOR_TEXT_WHITE);
