655	
656	    tft.setTextColor(COLOR_TEXT_MUTED);
657	    tft.setCursor(55, 160);
658	    tft.print(F("RETRACT CARD & RETRY"));
659	}
660	
661	// ============================================================================
662	// 12. SERIAL DEBUGGING & INTERACTIVE COMMAND INTERFACE
663	// ============================================================================
664	void handleSerialCommands() {
665	    if (!Serial.available()) return;
666	
667	    String cmd = Serial.readStringUntil('\n');
668	    cmd.trim();
669	
670	    if (cmd.equalsIgnoreCase("help")) {
671	        Serial.println(F("\n--- [VGWD025K3 COMMAND CONSOLE] ---"));
672	        Serial.println(F("  power          - Print deep power management status"));
673	        Serial.println(F("  status         - Print current system telemetry & state"));
674	        Serial.println(F("  log            - Display all logged entries from flash"));
675	        Serial.println(F("  play <track>   - Test play audio track (e.g. 'play 1', 'play 6')"));
676	        Serial.println(F("  vol <0-30>     - Set audio volume (e.g. 'vol 25')"));
677	        Serial.println(F("  cancel         - Abort current running timer session"));
678	        Serial.println(F("  set_time <sec> - Set timer duration in seconds (10 to 7200)"));
679	        Serial.println(F("  help           - Print this menu"));
680	        Serial.println(F("----------------------------------\n"));
681	    }
682	    else if (cmd.equalsIgnoreCase("power")) {
683	        Serial.println(F("\n=================================================="));
684	        Serial.println(F(">>>       SYSTEM ENERGY & POWER TELEMETRY      <<<"));
685	        Serial.println(F("=================================================="));
686	        Serial.printf("  ├─ CPU Core Frequency : %d MHz (Downclocked for 60%% power cut)\n", getCpuFrequencyMhz());
687	        Serial.printf("  ├─ Wi-Fi Modem State  : %s (PHY / Baseband Powered Off)\n", WiFi.getMode() == WIFI_OFF ? "DISABLED (0.0 mA)" : "ACTIVE");
688	        Serial.printf("  ├─ Bluetooth Engine   : %s (Controller Clock Gated)\n", esp_bt_controller_get_status() == ESP_BT_CONTROLLER_STATUS_IDLE ? "DISABLED (0.0 mA)" : "ACTIVE");
689	        Serial.printf("  ├─ MFRC522 Power State: %s\n", rfidHardSleeping ? "HARD POWER-DOWN (0.2 µA - RST Clamped LOW)" : "ACTIVE / ENERGIZED (RxGain Max)");
690	        Serial.printf("  └─ Active System State: %d\n", currentState);
691	        Serial.println(F("==================================================\n"));
692	    }
693	    else if (cmd.equalsIgnoreCase("log")) {
694	        Serial.println(F("\n[STORAGE] Reading log from flash..."));
695	        readLogFromFlash();
696	        Serial.println();
697	    }
698	    else if (cmd.startsWith("play")) {
699	        int spaceIdx = cmd.indexOf(' ');
700	        if (spaceIdx > 0) {
701	            uint16_t track = cmd.substring(spaceIdx + 1).toInt();
702	            Serial.printf("[AUDIO] Manual test: Playing track %d...\n", track);
703	            audio.playTrack(track);
704	        }
705	    }
706	    else if (cmd.startsWith("vol")) {
707	        int spaceIdx = cmd.indexOf(' ');
708	        if (spaceIdx > 0) {
709	            uint8_t vol = cmd.substring(spaceIdx + 1).toInt();
710	            audio.setVolume(vol);
711	            Serial.printf("[AUDIO] Volume set to %d/30.\n", vol);
712	        }
713	    }
714	    else if (cmd.equalsIgnoreCase("status")) {
715	        Serial.println(F("\n--- [SYSTEM TELEMETRY] ---"));
716	        Serial.printf("  Current State : %d\n", currentState);
717	        Serial.printf("  Last Card UID : %s\n", currentCardUID.c_str());
718	        Serial.printf("  Timer Setting : %u seconds (%02u:%02u)\n", timerDurationSeconds, timerDurationSeconds / 60, timerDurationSeconds % 60);
719	        Serial.printf("  RFID Hardware : %s\n", rfidHardSleeping ? "0.2µA Hard Sleep" : "Awake & Energized");
720	        Serial.printf("  CPU Clock     : %d MHz\n", getCpuFrequencyMhz());
721	        Serial.println(F("--------------------------\n"));
722	    }
723	    else if (cmd.equalsIgnoreCase("cancel")) {
724	        if (currentState == STATE_TIMER_RUNNING) {
725	            Serial.println(F("[CMD] Active timer cancelled by user command."));
726	            audio.stop();
727	            transitionToState(STATE_IDLE_READY);
728	        } else {
729	            Serial.println(F("[CMD] No active timer running to cancel."));
730	        }
731	    }
732	    else if (cmd.startsWith("set_time")) {
733	        int spaceIdx = cmd.indexOf(' ');
734	        if (spaceIdx > 0) {
735	            uint32_t val = cmd.substring(spaceIdx + 1).toInt();
736	            if (val >= TIMER_MIN_SECONDS && val <= TIMER_MAX_SECONDS) {
737	                timerDurationSeconds = val;
738	                Serial.printf("[CMD] Timer duration updated to %u seconds (%02u:%02u).\n",
739	                              timerDurationSeconds, timerDurationSeconds / 60, timerDurationSeconds % 60);
740	                if (currentState == STATE_IDLE_READY) {
741	                    drawIdleScreen();
742	                }
743	            } else {
744	                Serial.printf("[CMD] Error: Duration must be between %d and %d seconds.\n",
