bool connectWiFi() {
    Serial.printf("\n[WIFI] Connecting to \"%s\"...\n", WIFI_SSID);

    drawStatusScreen("CONNECTING", WIFI_SSID, "Please wait...", COLOR_CYAN_GLOW);

    WiFi.mode(WIFI_STA);
    WiFi.begin(WIFI_SSID, WIFI_PASSWORD);

    uint32_t startMs = millis();
    while (WiFi.status() != WL_CONNECTED) {
        if (millis() - startMs > WIFI_TIMEOUT_MS) {
            Serial.println(F("[WIFI] TIMEOUT — connection failed."));
            drawStatusScreen("WIFI FAILED", "Check SSID/PASS", "or backend power", COLOR_CRIMSON);
            return false;
        }
        delay(500);
        Serial.print(".");
    }

    String ip = WiFi.localIP().toString();
    Serial.printf("\n[WIFI] Connected! IP: %s | RSSI: %d dBm\n",
                  ip.c_str(), WiFi.RSSI());

    char ipBuf[20];
    ip.toCharArray(ipBuf, sizeof(ipBuf));
    drawStatusScreen("WIFI OK", ipBuf, "Contacting backend...", COLOR_EMERALD);
    delay(1200); // Let the Manager read the IP

    return true;
}

// ============================================================================
// 7. BACKEND FETCH
// ============================================================================

bool fetchAndDisplayTriplet() {
    Serial.println(F("\n[BACKEND] Fetching triplet queue..."));
    Serial.printf("[BACKEND] GET %s\n", BACKEND_QUEUE);

    HTTPClient http;
    http.begin(BACKEND_QUEUE);
    http.setTimeout(8000); // 8s timeout for first contact

    int httpCode = http.GET();

    // ── HTTP-level failure ──────────────────────────────────────────────────
    if (httpCode <= 0) {
        Serial.printf("[BACKEND] HTTP error: %s\n", http.errorToString(httpCode).c_str());
        drawStatusScreen("BACKEND ERR", "Cannot reach server", "Is backend running?", COLOR_CRIMSON);
        http.end();
        return false;
    }

    if (httpCode != 200) {
        Serial.printf("[BACKEND] Unexpected HTTP %d\n", httpCode);
        char codeBuf[24];
        snprintf(codeBuf, sizeof(codeBuf), "HTTP %d returned", httpCode);
        drawStatusScreen("BACKEND ERR", codeBuf, "Check server logs", COLOR_CRIMSON);
        http.end();
        return false;
    }

    // ── Read & dump raw payload ─────────────────────────────────────────────
    String payload = http.getString();
    http.end();

    Serial.println(F("\n[BACKEND] ===== RAW RESPONSE ====="));
    Serial.println(payload);
    Serial.println(F("[BACKEND] ===========================\n"));

    // ── JSON parse ──────────────────────────────────────────────────────────
    // Doc sized for 3 tasks with full metadata + outer fields
    JsonDocument doc;
    DeserializationError err = deserializeJson(doc, payload);

    if (err) {
        Serial.printf("[BACKEND] JSON parse error: %s\n", err.c_str());
        drawStatusScreen("JSON ERR", err.c_str(), "Bad response body", COLOR_CRIMSON);
        return false;
    }

    // ── Validate shape ──────────────────────────────────────────────────────
    if (!doc["success"].as<bool>()) {
        Serial.println(F("[BACKEND] Response indicates failure (success: false)."));
        drawStatusScreen("TASK ERR", "success: false", "Check backend logs", COLOR_CRIMSON);
        return false;
    }

    int totalInQueue = doc["total_in_queue"].as<int>();
    int count        = doc["count"].as<int>();
    const char* selectedList = doc["selected_list"] | "all";
    const char* lastSynced   = doc["last_synced_at"] | "unknown";

    // ── Serial: structured triplet dump ────────────────────────────────────
    Serial.println(F("========================================"));
    Serial.println(F("[ESP32] GOLDEN HOUR — TRIPLET FOCUS QUEUE"));
    Serial.printf("  Total in queue  : %d tasks\n", totalInQueue);
    Serial.printf("  Tasks returned  : %d\n", count);
    Serial.printf("  Selected list   : %s\n", selectedList);
    Serial.printf("  Last synced     : %s\n", lastSynced);
    Serial.println(F("  ----------------------------------------"));

    JsonArray tasks = doc["tasks"].as<JsonArray>();
    int i = 0;
    for (JsonObject task : tasks) {
        Serial.printf("  [%d] Title      : %s\n", task["index"].as<int>(), task["title"].as<const char*>());
        Serial.printf("       List       : %s\n", task["tasklist_title"].as<const char*>());
        Serial.printf("       Task ID    : %s\n", task["task_id"].as<const char*>());
        Serial.printf("       List ID    : %s\n", task["tasklist_id"].as<const char*>());
        const char* due = task["due"] | "none";
        Serial.printf("       Due        : %s\n", due);
        Serial.println(F("  ----------------------------------------"));
        i++;
    }

    Serial.println(F("========================================\n"));

    // ── Display top task on LCD ─────────────────────────────────────────────
    JsonObject topTask = doc["top_task"];
    const char* topTitle     = topTask["title"]    | "No task";
    const char* topListTitle = tasks[0]["tasklist_title"] | "Unknown";
    int topIndex             = topTask["index"].as<int>();

    drawTripletScreen(topTitle, topListTitle, topIndex, totalInQueue);

    return true;
}

