 *   2. Hit GET /api/v1/golden-hour/esp32/queue?limit=3 on the local backend
 *   3. Display backend connection status + top task title on the round LCD
 *   4. Dump full triplet JSON to Serial for acceptance verification
 *
 * Hardware: ESP32-WROOM-32 | GC9A01A 240x240 Round TFT (HSPI)
 * Temporal Arc: Arc 3, 2026
 * Architect: The Manager & Faust
 * ============================================================================
 */

#include <Arduino.h>
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_GC9A01A.h>
#include <WiFi.h>
#include <HTTPClient.h>
#include <ArduinoJson.h>

// ============================================================================
// 1. CONFIGURATION
// ============================================================================

// Wi-Fi credentials
#define WIFI_SSID       "Phong tro 222"
#define WIFI_PASSWORD   "158a32222"

// Backend base URL (local PC running Golden Hour backend)
#define BACKEND_HOST    "http://192.168.2.16:8080"
#define BACKEND_QUEUE   BACKEND_HOST "/api/v1/golden-hour/esp32/queue?limit=3"

// Wi-Fi connect timeout
#define WIFI_TIMEOUT_MS 15000

// ============================================================================
// 2. HARDWARE PIN MATRIX (HSPI for GC9A01 — unchanged from Arc 3 MVP)
// ============================================================================

#define PIN_LCD_SCK     15   // HSPI Clock
#define PIN_LCD_MOSI     2   // HSPI MOSI
#define PIN_TFT_DC       4   // Data/Command
#define PIN_TFT_CS      16   // Chip Select
#define PIN_TFT_RST     17   // Hardware Reset

// Display geometry
#define TFT_CENTER_X    120
#define TFT_CENTER_Y    120

// Color palette
#define COLOR_BG        0x0000   // Pure Black
#define COLOR_HUD_RING  0x18E3   // Dark Tech Cyan
#define COLOR_CYAN_GLOW 0x07FF   // Bright Cyan
#define COLOR_GOLD      0xFDE0   // Gold Accent
#define COLOR_CRIMSON   0xF800   // Error Red
#define COLOR_EMERALD   0x07E0   // Success Green
#define COLOR_TEXT_WHITE 0xFFFF  // Crisp White
#define COLOR_TEXT_MUTED 0x7BEF  // Dim Grey

// ============================================================================
// 3. GLOBAL OBJECTS
// ============================================================================

SPIClass hspi(HSPI);
Adafruit_GC9A01A tft(&hspi, PIN_TFT_DC, PIN_TFT_CS, PIN_TFT_RST);

// ============================================================================
// 4. FORWARD DECLARATIONS
// ============================================================================

void drawStatusScreen(const char* line1, const char* line2,
                      const char* line3, uint16_t ringColor);
void drawTripletScreen(const char* taskTitle, const char* listTitle,
                       int taskIndex, int totalInQueue);
bool connectWiFi();
bool fetchAndDisplayTriplet();

// ============================================================================
// 5. DISPLAY HELPERS
// ============================================================================

/**
 * Generic 3-line status screen with a color-coded outer ring.
 * Used for: connecting, error, and intermediate states.
 */
void drawStatusScreen(const char* line1, const char* line2,
                      const char* line3, uint16_t ringColor) {
    tft.fillScreen(COLOR_BG);
    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 115, ringColor);
    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 112, COLOR_HUD_RING);

    // Header
    tft.setTextSize(1);
    tft.setTextColor(COLOR_GOLD);
    tft.setCursor(68, 50);
    tft.print(F("VARIS GEAR VGWD"));

    // Line 1 — primary status label (e.g. "CONNECTING...")
    tft.setTextSize(2);
    tft.setTextColor(ringColor);
    int16_t x1 = TFT_CENTER_X - (strlen(line1) * 12 / 2);
    tft.setCursor(x1, 95);
    tft.print(line1);

    // Line 2 — secondary info (e.g. SSID or error description)
    tft.setTextSize(1);
    tft.setTextColor(COLOR_TEXT_WHITE);
    int16_t x2 = TFT_CENTER_X - (strlen(line2) * 6 / 2);
    tft.setCursor(x2, 130);
    tft.print(line2);

    // Line 3 — tertiary info (e.g. IP or retry hint)
    tft.setTextColor(COLOR_TEXT_MUTED);
    int16_t x3 = TFT_CENTER_X - (strlen(line3) * 6 / 2);
    tft.setCursor(x3, 148);
    tft.print(line3);
}

/**
 * Task display screen — shows the top task from the backend triplet.
 * Renders: task index/total, list name, and full task title (wrapped).
 */
void drawTripletScreen(const char* taskTitle, const char* listTitle,
                       int taskIndex, int totalInQueue) {
    tft.fillScreen(COLOR_BG);

    // Emerald ring = success / live data
    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 115, COLOR_EMERALD);
    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 112, COLOR_CYAN_GLOW);

    // Header label
    tft.setTextSize(1);
    tft.setTextColor(COLOR_GOLD);
    tft.setCursor(68, 48);
    tft.print(F("GOLDEN HOUR"));

    // Queue counter (e.g. "#1 of 431")
    char counterBuf[24];
    snprintf(counterBuf, sizeof(counterBuf), "#%d of %d tasks", taskIndex, totalInQueue);
    tft.setTextColor(COLOR_TEXT_MUTED);
    int16_t cx = TFT_CENTER_X - (strlen(counterBuf) * 6 / 2);
    tft.setCursor(cx, 62);
    tft.print(counterBuf);

    // Divider line
    tft.drawFastHLine(40, 78, 160, COLOR_HUD_RING);

    // List name (e.g. "Green")
    tft.setTextColor(COLOR_CYAN_GLOW);
    tft.setTextSize(1);
    char listBuf[32];
    snprintf(listBuf, sizeof(listBuf), "[%s]", listTitle);
    int16_t lx = TFT_CENTER_X - (strlen(listBuf) * 6 / 2);
    tft.setCursor(lx, 88);
    tft.print(listBuf);

    // Task title — up to 20 chars per line, 2 lines max
    tft.setTextSize(2);
    tft.setTextColor(COLOR_TEXT_WHITE);

    String title = String(taskTitle);
    if (title.length() <= 10) {
        // Short title — center on one line
        int16_t tx = TFT_CENTER_X - (title.length() * 12 / 2);
        tft.setCursor(tx, 108);
        tft.print(title);
    } else if (title.length() <= 20) {
        // Medium title — one line, left-anchored
        tft.setCursor(20, 108);
        tft.print(title);
    } else {
        // Long title — wrap at 10 chars (size 2 = 12px/char, ~10 chars fit cleanly)
        tft.setCursor(20, 100);
        tft.print(title.substring(0, 10));
        tft.setCursor(20, 122);
        tft.print(title.substring(10, 20));
    }

    // Divider line
    tft.drawFastHLine(40, 152, 160, COLOR_HUD_RING);

    // Backend connected indicator
    tft.setTextSize(1);
    tft.setTextColor(COLOR_EMERALD);
    tft.setCursor(62, 162);
    tft.print(F("BACKEND: ONLINE"));

    // IP address footer
    tft.setTextColor(COLOR_TEXT_MUTED);
    String ipStr = WiFi.localIP().toString();
    int16_t ipx = TFT_CENTER_X - (ipStr.length() * 6 / 2);
    tft.setCursor(ipx, 178);
    tft.print(ipStr);
}

// ============================================================================
// 6. WIFI CONNECTION
// ============================================================================

bool connectWiFi() {
    Serial.printf("\n[WIFI] Connecting to \"%s\"...\n", WIFI_SSID);

    drawStatusScreen("CONNECTING", WIFI_SSID, "Please wait...", COLOR_CYAN_GLOW);

    WiFi.mode(WIFI_STA);
    WiFi.begin(WIFI_SSID, WIFI_PASSWORD);

    uint32_t startMs = millis();
    while (WiFi.status() != WL_CONNECTED) {
        if (millis() - startMs > WIFI_TIMEOUT_MS) {
            Serial.println(F("[WIFI] TIMEOUT — connection failed."));
            drawStatusScreen("WIFI FAILED", "Check SSID/PASS", "or backend power", COLOR_CRIMSON);
            return false;
        }
        delay(500);
        Serial.print(".");
    }

    String ip = WiFi.localIP().toString();
    Serial.printf("\n[WIFI] Connected! IP: %s | RSSI: %d dBm\n",
                  ip.c_str(), WiFi.RSSI());

    char ipBuf[20];
    ip.toCharArray(ipBuf, sizeof(ipBuf));
    drawStatusScreen("WIFI OK", ipBuf, "Contacting backend...", COLOR_EMERALD);
    delay(1200); // Let the Manager read the IP

    return true;
}

// ============================================================================
// 7. BACKEND FETCH
// ============================================================================

bool fetchAndDisplayTriplet() {
    Serial.println(F("\n[BACKEND] Fetching triplet queue..."));
    Serial.printf("[BACKEND] GET %s\n", BACKEND_QUEUE);

    HTTPClient http;
    http.begin(BACKEND_QUEUE);
    http.setTimeout(8000); // 8s timeout for first contact

    int httpCode = http.GET();

    // ── HTTP-level failure ──────────────────────────────────────────────────
    if (httpCode <= 0) {
        Serial.printf("[BACKEND] HTTP error: %s\n", http.errorToString(httpCode).c_str());
        drawStatusScreen("BACKEND ERR", "Cannot reach server", "Is backend running?", COLOR_CRIMSON);
        http.end();
        return false;
    }

    if (httpCode != 200) {
        Serial.printf("[BACKEND] Unexpected HTTP %d\n", httpCode);
        char codeBuf[24];
        snprintf(codeBuf, sizeof(codeBuf), "HTTP %d returned", httpCode);
        drawStatusScreen("BACKEND ERR", codeBuf, "Check server logs", COLOR_CRIMSON);
        http.end();
        return false;
    }

    // ── Read & dump raw payload ─────────────────────────────────────────────
    String payload = http.getString();
    http.end();

    Serial.println(F("\n[BACKEND] ===== RAW RESPONSE ====="));
    Serial.println(payload);
    Serial.println(F("[BACKEND] ===========================\n"));

    // ── JSON parse ──────────────────────────────────────────────────────────
    // Doc sized for 3 tasks with full metadata + outer fields
    JsonDocument doc;
    DeserializationError err = deserializeJson(doc, payload);

    if (err) {
        Serial.printf("[BACKEND] JSON parse error: %s\n", err.c_str());
        drawStatusScreen("JSON ERR", err.c_str(), "Bad response body", COLOR_CRIMSON);
        return false;
    }

    // ── Validate shape ──────────────────────────────────────────────────────
    if (!doc["success"].as<bool>()) {
        Serial.println(F("[BACKEND] Response indicates failure (success: false)."));
        drawStatusScreen("TASK ERR", "success: false", "Check backend logs", COLOR_CRIMSON);
        return false;
    }

    int totalInQueue = doc["total_in_queue"].as<int>();
    int count        = doc["count"].as<int>();
    const char* selectedList = doc["selected_list"] | "all";
    const char* lastSynced   = doc["last_synced_at"] | "unknown";

    // ── Serial: structured triplet dump ────────────────────────────────────
    Serial.println(F("========================================"));
    Serial.println(F("[ESP32] GOLDEN HOUR — TRIPLET FOCUS QUEUE"));
    Serial.printf("  Total in queue  : %d tasks\n", totalInQueue);
    Serial.printf("  Tasks returned  : %d\n", count);
    Serial.printf("  Selected list   : %s\n", selectedList);
    Serial.printf("  Last synced     : %s\n", lastSynced);
    Serial.println(F("  ----------------------------------------"));

    JsonArray tasks = doc["tasks"].as<JsonArray>();
    int i = 0;
    for (JsonObject task : tasks) {
        Serial.printf("  [%d] Title      : %s\n", task["index"].as<int>(), task["title"].as<const char*>());
        Serial.printf("       List       : %s\n", task["tasklist_title"].as<const char*>());
        Serial.printf("       Task ID    : %s\n", task["task_id"].as<const char*>());
        Serial.printf("       List ID    : %s\n", task["tasklist_id"].as<const char*>());
        const char* due = task["due"] | "none";
        Serial.printf("       Due        : %s\n", due);
        Serial.println(F("  ----------------------------------------"));
        i++;
    }

    Serial.println(F("========================================\n"));

    // ── Display top task on LCD ─────────────────────────────────────────────
    JsonObject topTask = doc["top_task"];
    const char* topTitle     = topTask["title"]    | "No task";
    const char* topListTitle = tasks[0]["tasklist_title"] | "Unknown";
    int topIndex             = topTask["index"].as<int>();

    drawTripletScreen(topTitle, topListTitle, topIndex, totalInQueue);

    return true;
}

// ============================================================================
// 8. SETUP
// ============================================================================

void setup() {
    // Run at full 240MHz — Wi-Fi stack needs it; no power saving in this phase
    setCpuFrequencyMhz(240);

    Serial.begin(115200);
    delay(200);

    Serial.println();
    Serial.println(F("**************************************************"));
    Serial.println(F("*  VGWD025K3 ~ CODEX OF TIME                    *"));
    Serial.println(F("*  Tab 2: GOLDEN HOUR — Backend Handshake POC   *"));
    Serial.println(F("*  ESP32-WROOM-32 | GC9A01 240x240 Round TFT   *"));
    Serial.println(F("**************************************************"));
    Serial.printf ("[SYSTEM] CPU: %d MHz\n", getCpuFrequencyMhz());

    // --- Display init (HSPI) -----------------------------------------------
    pinMode(PIN_TFT_CS,  OUTPUT);
    digitalWrite(PIN_TFT_CS, HIGH);

    hspi.begin(PIN_LCD_SCK, -1, PIN_LCD_MOSI, PIN_TFT_CS);
    tft.begin();
    tft.setRotation(2);
    tft.fillScreen(COLOR_BG);

    Serial.println(F("[DISPLAY] GC9A01 online."));

    // --- Wi-Fi + Backend ---------------------------------------------------
    if (!connectWiFi()) {
        // Fatal: halts in error state; physical reset required
        Serial.println(F("[SYSTEM] HALT — Wi-Fi failed. Reset device to retry."));
        while (true) delay(1000);
    }

    if (!fetchAndDisplayTriplet()) {
        Serial.println(F("[SYSTEM] HALT — Backend fetch failed. Check server."));
        while (true) delay(1000);
    }

    Serial.println(F("[SYSTEM] Handshake complete. Triplet displayed on LCD."));
}

// ============================================================================
// 9. LOOP — idle, nothing to poll yet
// ============================================================================

void loop() {
    // Phase 1 is display-only. Buttons, navigation, and complete
    // logic will be wired in the next phase once the handshake is proven.
    delay(1000);
}

