/**
 * ============================================================================
 * VGWD025K3 ~ Codex of Time — Wi-Fi Connectivity Test
 *
 * Objective:
 *   Verify ESP32 can connect to phone hotspot and reach the open internet.
 *
 * Acceptance criteria (Serial + LCD):
 *   1. Wi-Fi connects to "Redmi K60 Ultra"
 *   2. HTTP GET to http://httpbin.org/get returns 200
 *   3. LCD shows green ring + assigned IP + RSSI + "INTERNET OK"
 *
 * Hardware: ESP32-WROOM-32 | GC9A01A 240x240 Round TFT (HSPI)
 * Architect: The Manager & Faust
 * ============================================================================
 */

#include <Arduino.h>
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_GC9A01A.h>
#include <WiFi.h>
#include <HTTPClient.h>

// ============================================================================
// 1. CONFIGURATION
// ============================================================================

#define WIFI_SSID        "Redmi K60 Ultra"
#define WIFI_PASSWORD    "toiyeufaust"
#define WIFI_TIMEOUT_MS  20000   // 20s — generous for hotspot cold-start

// A dead-simple public endpoint — returns JSON echo of the request.
// No API key, no auth, always up.
#define PING_URL         "http://httpbin.org/get"

// ============================================================================
// 2. HARDWARE PINS (HSPI → GC9A01A, unchanged from Arc 3)
// ============================================================================

#define PIN_LCD_SCK      15
#define PIN_LCD_MOSI      2
#define PIN_TFT_DC        4
#define PIN_TFT_CS       16
#define PIN_TFT_RST      17

#define TFT_CENTER_X     120
#define TFT_CENTER_Y     120

// Color palette
#define COLOR_BG         0x0000
#define COLOR_HUD_RING   0x18E3
#define COLOR_CYAN_GLOW  0x07FF
#define COLOR_GOLD       0xFDE0
#define COLOR_CRIMSON    0xF800
#define COLOR_EMERALD    0x07E0
#define COLOR_TEXT_WHITE 0xFFFF
#define COLOR_TEXT_MUTED 0x7BEF

// ============================================================================
// 3. GLOBALS
// ============================================================================

SPIClass hspi(HSPI);
Adafruit_GC9A01A tft(&hspi, PIN_TFT_DC, PIN_TFT_CS, PIN_TFT_RST);

// ============================================================================
// 4. DISPLAY
// ============================================================================

void drawStatusScreen(const char* label, const char* line2,
                      const char* line3, const char* line4,
                      uint16_t ringColor) {
    tft.fillScreen(COLOR_BG);
    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 115, ringColor);
    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 112, COLOR_HUD_RING);

    // Header
    tft.setTextSize(1);
    tft.setTextColor(COLOR_GOLD);
    tft.setCursor(68, 45);
    tft.print(F("VARIS GEAR VGWD"));

    // Primary label (big)
    tft.setTextSize(2);
    tft.setTextColor(ringColor);
    tft.setCursor(TFT_CENTER_X - (strlen(label) * 12 / 2), 88);
    tft.print(label);

    // Line 2
    tft.setTextSize(1);
    tft.setTextColor(COLOR_TEXT_WHITE);
    tft.setCursor(TFT_CENTER_X - (strlen(line2) * 6 / 2), 120);
    tft.print(line2);

    // Line 3
    tft.setTextColor(COLOR_TEXT_MUTED);
    tft.setCursor(TFT_CENTER_X - (strlen(line3) * 6 / 2), 136);
    tft.print(line3);

    // Line 4
    tft.setCursor(TFT_CENTER_X - (strlen(line4) * 6 / 2), 152);
    tft.print(line4);
}

void drawSuccessScreen(const char* ip, int rssi, int httpCode) {
    tft.fillScreen(COLOR_BG);
    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 115, COLOR_EMERALD);
    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 112, COLOR_CYAN_GLOW);

    tft.setTextSize(1);
    tft.setTextColor(COLOR_GOLD);
    tft.setCursor(68, 45);
    tft.print(F("VARIS GEAR VGWD"));

    tft.drawFastHLine(40, 58, 160, COLOR_HUD_RING);

    // INTERNET OK — big green
    tft.setTextSize(2);
    tft.setTextColor(COLOR_EMERALD);
    tft.setCursor(28, 72);
    tft.print(F("INTERNET OK"));

    tft.drawFastHLine(40, 96, 160, COLOR_HUD_RING);

    // IP
    tft.setTextSize(1);
    tft.setTextColor(COLOR_TEXT_WHITE);
    tft.setCursor(TFT_CENTER_X - (strlen(ip) * 6 / 2), 108);
    tft.print(ip);

    // RSSI
    char rssiBuf[24];
    snprintf(rssiBuf, sizeof(rssiBuf), "RSSI: %d dBm", rssi);
    tft.setTextColor(rssi > -70 ? COLOR_EMERALD : COLOR_GOLD);
    tft.setCursor(TFT_CENTER_X - (strlen(rssiBuf) * 6 / 2), 124);
    tft.print(rssiBuf);

    // HTTP status
    char httpBuf[24];
    snprintf(httpBuf, sizeof(httpBuf), "HTTP %d from web", httpCode);
    tft.setTextColor(COLOR_TEXT_MUTED);
    tft.setCursor(TFT_CENTER_X - (strlen(httpBuf) * 6 / 2), 140);
    tft.print(httpBuf);

    // SSID
    tft.setTextColor(COLOR_CYAN_GLOW);
    tft.setCursor(TFT_CENTER_X - (strlen(WIFI_SSID) * 6 / 2), 162);
    tft.print(WIFI_SSID);
}

// ============================================================================
// 5. WI-FI
// ============================================================================

bool connectWiFi() {
    Serial.printf("\n[WIFI] Connecting to \"%s\"...\n", WIFI_SSID);

    drawStatusScreen("CONNECTING", WIFI_SSID, "Please wait...", "", COLOR_CYAN_GLOW);

    WiFi.mode(WIFI_STA);
    WiFi.setAutoReconnect(true);   // re-latch automatically if hotspot drops
    WiFi.begin(WIFI_SSID, WIFI_PASSWORD);

    uint32_t t0 = millis();
    while (WiFi.status() != WL_CONNECTED) {
        if (millis() - t0 > WIFI_TIMEOUT_MS) {
            Serial.println(F("\n[WIFI] TIMEOUT."));
            drawStatusScreen("WIFI FAILED", "Check band: 2.4GHz?", "SSID/PASS correct?",
                             "Reset to retry", COLOR_CRIMSON);
            return false;
        }
        delay(500);
        Serial.print(".");
    }

    String ip   = WiFi.localIP().toString();
    int    rssi = WiFi.RSSI();
    Serial.printf("\n[WIFI] Connected!\n");
    Serial.printf("  IP   : %s\n", ip.c_str());
    Serial.printf("  RSSI : %d dBm\n", rssi);
    Serial.printf("  GW   : %s\n", WiFi.gatewayIP().toString().c_str());

    char ipBuf[20];
    ip.toCharArray(ipBuf, sizeof(ipBuf));
    drawStatusScreen("WIFI OK", ipBuf, "Testing internet...", "", COLOR_EMERALD);
    delay(900);

    return true;
}

// ============================================================================
// 6. INTERNET PING
// ============================================================================

bool pingInternet() {
    Serial.printf("\n[NET] GET %s\n", PING_URL);

    HTTPClient http;
    http.begin(PING_URL);
    http.setTimeout(10000);

    int code = http.GET();

    if (code == 200) {
        String body = http.getString();
        http.end();

        Serial.println(F("[NET] ===== RESPONSE ====="));
        // Print first 300 chars — httpbin returns a JSON blob
        Serial.println(body.substring(0, 300));
        Serial.println(F("[NET] ========================\n"));
        Serial.println(F("[NET] INTERNET REACHABLE — handshake complete."));

        String ip = WiFi.localIP().toString();
        char ipBuf[20];
        ip.toCharArray(ipBuf, sizeof(ipBuf));
        drawSuccessScreen(ipBuf, WiFi.RSSI(), code);
        return true;
    }

    // Non-200 or error
    if (code < 0) {
        Serial.printf("[NET] Error: %s\n", http.errorToString(code).c_str());
    } else {
        Serial.printf("[NET] HTTP %d\n", code);
    }
    http.end();

    char codeBuf[28];
    snprintf(codeBuf, sizeof(codeBuf), "HTTP %d / %s",
             code, code < 0 ? "conn err" : "unexpected");
    drawStatusScreen("NET FAILED", "Wi-Fi up, web down?", codeBuf,
                     "Reset to retry", COLOR_CRIMSON);
    return false;
}

// ============================================================================
// 7. SETUP
// ============================================================================

void setup() {
    setCpuFrequencyMhz(240);
    Serial.begin(115200);
    delay(200);

    Serial.println(F("\n**************************************************"));
    Serial.println(F("*  VGWD025K3 ~ CODEX OF TIME                    *"));
    Serial.println(F("*  Phase: Wi-Fi + Internet Connectivity Test     *"));
    Serial.println(F("**************************************************"));

    // Display init
    pinMode(PIN_TFT_CS, OUTPUT);
    digitalWrite(PIN_TFT_CS, HIGH);
    hspi.begin(PIN_LCD_SCK, -1, PIN_LCD_MOSI, PIN_TFT_CS);
    tft.begin();
    tft.setRotation(2);
    tft.fillScreen(COLOR_BG);
    Serial.println(F("[DISPLAY] GC9A01 online."));

    // Step 1: Wi-Fi
    if (!connectWiFi()) {
        Serial.println(F("[SYSTEM] HALT — Wi-Fi failed."));
        while (true) delay(1000);
    }

    // Step 2: Internet
    if (!pingInternet()) {
        Serial.println(F("[SYSTEM] HALT — Internet unreachable."));
        while (true) delay(1000);
    }

    Serial.println(F("[SYSTEM] All checks passed. ESP32 is live on the internet."));
}

// ============================================================================
// 8. LOOP
// ============================================================================

void loop() {
    // Print RSSI every 10s so we can monitor signal quality from serial
    Serial.printf("[WIFI] Status: %s | RSSI: %d dBm\n",
                  WiFi.status() == WL_CONNECTED ? "CONNECTED" : "LOST",
                  WiFi.RSSI());
    delay(10000);
}

