/**
 * ============================================================================
 * VGWD025K3 ~ Codex of Time — Tab 2: Golden Hour (Task Engine) over Cloudflare Tunnel
 *
 * Objectives:
 *   1. Connect to phone hotspot (Redmi K60 Ultra) with auto-reconnect.
 *   2. Fetch task triplet from backend via Cloudflare Tunnel:
 *          GET https://faust.arc-system.id.vn/api/v1/golden-hour/esp32/queue?limit=3
 *   3. Display the top task on GC9A01 LCD (emerald ring) with:
 *          - GOLDEN HOUR header
 *          - Task index / total in queue
 *          - List name
 *          - Task title (wrapped)
 *          - Backend status + IP
 *   4. Log RSSI every 10s to Serial for link health.
 *
 * Hardware: ESP32-WROOM-32 | GC9A01A 240x240 Round TFT (HSPI)
 * Architect: The Manager & Faust
 * Temporal Arc: Arc 3, 2026
 * ============================================================================
 */

#include <Arduino.h>
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_GC9A01A.h>
#include <WiFi.h>
#include <WiFiClientSecure.h>
#include <HTTPClient.h>
#include <ArduinoJson.h>

// ============================================================================
// 1. CONFIGURATION
// ============================================================================

#define WIFI_SSID        "Redmi K60 Ultra"
#define WIFI_PASSWORD    "toiyeufaust"
#define WIFI_TIMEOUT_MS  20000

// Cloudflare Tunnel base URL (no trailing slash)
#define BACKEND_HOST     "https://faust.arc-system.id.vn"
// Full endpoint for triplet queue
#define TRIPLET_ENDPOINT BACKEND_HOST "/api/v1/golden-hour/esp32/queue?limit=3"

// ============================================================================
// 2. HARDWARE PIN MATRIX (HSPI for GC9A01)
// ============================================================================

#define PIN_LCD_SCK      15   // HSPI Clock
#define PIN_LCD_MOSI      2   // HSPI MOSI
#define PIN_TFT_DC        4   // Data/Command
#define PIN_TFT_CS       16   // Chip Select
#define PIN_TFT_RST      17   // Hardware Reset

// Display geometry
#define TFT_CENTER_X    120
#define TFT_CENTER_Y    120

// Color palette
#define COLOR_BG        0x0000   // Pure Black
#define COLOR_HUD_RING  0x18E3   // Dark Tech Cyan
#define COLOR_CYAN_GLOW 0x07FF   // Bright Cyan
#define COLOR_GOLD      0xFDE0   // Gold Accent
#define COLOR_CRIMSON   0xF800   // Hazard / Error Red
#define COLOR_EMERALD   0x07E0   // Success Green
#define COLOR_TEXT_WHITE 0xFFFF  // Crisp White
#define COLOR_TEXT_MUTED 0x7BEF  // Dim Grey Text

// ============================================================================
// 3. GLOBAL OBJECTS
// ============================================================================

SPIClass hspi(HSPI);
Adafruit_GC9A01A tft(&hspi, PIN_TFT_DC, PIN_TFT_CS, PIN_TFT_RST);

// ============================================================================
// 4. DISPLAY HELPERS
// ============================================================================

void drawStatusScreen(const char* label, const char* line2,
                      const char* line3, const char* line4,
                      uint16_t ringColor) {
    tft.fillScreen(COLOR_BG);
    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 115, ringColor);
    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 112, COLOR_HUD_RING);

    // Header
    tft.setTextSize(1);
    tft.setTextColor(COLOR_GOLD);
    tft.setCursor(68, 45);
    tft.print(F("VARIS GEAR VGWD"));

    // Primary label
    tft.setTextSize(2);
    tft.setTextColor(ringColor);
    tft.setCursor(TFT_CENTER_X - (strlen(label) * 12 / 2), 88);
    tft.print(label);

    // Line 2
    tft.setTextSize(1);
    tft.setTextColor(COLOR_TEXT_WHITE);
    tft.setCursor(TFT_CENTER_X - (strlen(line2) * 6 / 2), 120);
    tft.print(line2);

    // Line 3
    tft.setTextColor(COLOR_TEXT_MUTED);
    tft.setCursor(TFT_CENTER_X - (strlen(line3) * 6 / 2), 136);
    tft.print(line3);

    // Line 4
    tft.setCursor(TFT_CENTER_X - (strlen(line4) * 6 / 2), 152);
    tft.print(line4);
}

void drawTripletScreen(const char* taskTitle, const char* listTitle,
                       int taskIndex, int totalInQueue, const char* ip) {
    tft.fillScreen(COLOR_BG);

    // Success ring = emerald
    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 115, COLOR_EMERALD);
    tft.drawCircle(TFT_CENTER_X, TFT_CENTER_Y, 112, COLOR_CYAN_GLOW);

    // Header
    tft.setTextSize(1);
    tft.setTextColor(COLOR_GOLD);
    tft.setCursor(68, 48);
    tft.print(F("GOLDEN HOUR"));

    // Queue counter: "#1 of 431"
    char counterBuf[32];
    snprintf(counterBuf, sizeof(counterBuf), "#%d of %d", taskIndex, totalInQueue);
    tft.setTextSize(1);
    tft.setTextColor(COLOR_TEXT_MUTED);
    int16_t cx = TFT_CENTER_X - (strlen(counterBuf) * 6 / 2);
    tft.setCursor(cx, 62);
    tft.print(counterBuf);

    // Divider
    tft.drawFastHLine(40, 78, 160, COLOR_HUD_RING);

    // List name
    tft.setTextColor(COLOR_CYAN_GLOW);
    tft.setTextSize(1);
    char listBuf[32];
    snprintf(listBuf, sizeof(listBuf), "[%s]", listTitle);
    int16_t lx = TFT_CENTER_X - (strlen(listBuf) * 6 / 2);
    tft.setCursor(lx, 88);
    tft.print(listBuf);

    // Task title (size 2, wrap at ~10 chars per line)
    tft.setTextSize(2);
    tft.setTextColor(COLOR_TEXT_WHITE);
    String title = String(taskTitle);
    if (title.length() <= 10) {
        int16_t tx = TFT_CENTER_X - (title.length() * 12 / 2);
        tft.setCursor(tx, 108);
        tft.print(title);
    } else if (title.length() <= 20) {
        tft.setCursor(20, 108);
        tft.print(title);
    } else {
        tft.setCursor(20, 100);
        tft.print(title.substring(0, 10));
        tft.setCursor(20, 122);
        tft.print(title.substring(10, 20));
    }

    // Divider
    tft.drawFastHLine(40, 152, 160, COLOR_HUD_RING);

    // Backend connected + IP
    tft.setTextSize(1);
    tft.setTextColor(COLOR_EMERALD);
    tft.setCursor(62, 162);
    tft.print(F("BACKEND: ONLINE"));
    tft.setTextColor(COLOR_TEXT_MUTED);
    tft.setCursor(TFT_CENTER_X - (strlen(ip) * 6 / 2), 178);
    tft.print(ip);
}

// ============================================================================
// 5. WI-FI WITH AUTO-RECONNECT
// ============================================================================

bool connectWiFi() {
    Serial.printf("\n[WIFI] Connecting to \"%s\"...\n", WIFI_SSID);

    drawStatusScreen("CONNECTING", WIFI_SSID, "Please wait...", "", COLOR_CYAN_GLOW);

    WiFi.mode(WIFI_STA);
    WiFi.setAutoReconnect(true);     // vital for hotspot drop/rejoin
    WiFi.begin(WIFI_SSID, WIFI_PASSWORD);

    uint32_t t0 = millis();
    while (WiFi.status() != WL_CONNECTED) {
        if (millis() - t0 > WIFI_TIMEOUT_MS) {
            Serial.println(F("\n[WIFI] TIMEOUT."));
            drawStatusScreen("WIFI FAILED", "Band: 2.4GHz?", "SSID/PASS correct?", "Reset to retry", COLOR_CRIMSON);
            return false;
        }
        delay(500);
        Serial.print(".");
    }

    String ip   = WiFi.localIP().toString();
    int    rssi = WiFi.RSSI();
    Serial.printf("\n[WIFI] Connected! IP: %s | RSSI: %d dBm | GW: %s\n",
                  ip.c_str(), rssi, WiFi.gatewayIP().toString().c_str());

    char ipBuf[20];
    ip.toCharArray(ipBuf, sizeof(ipBuf));
    drawStatusScreen("WIFI OK", ipBuf, "Contacting backend...", "", COLOR_EMERALD);
    delay(900);

    return true;
}

// ============================================================================
// 6. FETCH TRIPLET FROM BACKEND (HTTPS)
// ============================================================================

bool fetchAndDisplayTriplet() {
    Serial.printf("\n[BACKEND] GET %s\n", TRIPLET_ENDPOINT);

    // Use WiFiClientSecure for HTTPS; we'll accept any cert (Cloudflare is valid, but simple)
    WiFiClientSecure client;
    client.setInsecure();   // skip cert verification — OK for trusted tunnel in this context

    HTTPClient https;
    https.begin(client, TRIPLET_ENDPOINT);
    https.setTimeout(10000);

    int httpCode = https.GET();

    if (httpCode != 200) {
        Serial.printf("[BACKEND] HTTP error: %d\n", httpCode);
        if (httpCode <= 0) {
            Serial.printf("[BACKEND] Connection error: %s\n", https.errorToString(httpCode).c_str());
        }
        https.end();

        char codeBuf[24];
        snprintf(codeBuf, sizeof(codeBuf), "HTTP %d", httpCode);
        drawStatusScreen("BACKEND ERR", codeBuf, "Check tunnel/server", "Reset to retry", COLOR_CRIMSON);
        return false;
    }

    String payload = https.getString();
    https.end();

    Serial.println(F("\n[BACKEND] ====== RESPONSE ======="));
    Serial.println(payload);
    Serial.println(F("[BACKEND] =======================\n"));

    // Parse JSON
    const size_t CAPACITY = JSON_ARRAY_SIZE(3) + 5 * JSON_OBJECT_SIZE(3) + 2 * JSON_OBJECT_SIZE(4) + 200;
    DynamicJsonDocument doc(CAPACITY);

    DeserializationError err = deserializeJson(doc, payload);
    if (err) {
        Serial.printf("[BACKEND] JSON parse error: %s\n", err.c_str());
        drawStatusScreen("JSON ERR", err.c_str(), "Bad response", "Reset to retry", COLOR_CRIMSON);
        return false;
    }

    if (!doc["success"].as<bool>()) {
        Serial.println(F("[BACKEND] success == false"));
        drawStatusScreen("BACKEND ERR", "success: false", "See serial log", "Reset to retry", COLOR_CRIMSON);
        return false;
    }

    // Extract needed fields
    int totalInQueue = doc["total_in_queue"] | 0;
    int count        = doc["count"] | 0;
    JsonArray tasks  = doc["tasks"].as<JsonArray>();
    JsonObject top   = doc["top_task"];

    if (tasks.size() == 0 || !top) {
        Serial.println(F("[BACKEND] empty tasks"));
        drawStatusScreen("NO TASKS", "Triplet empty", "Wait for sync", "Reset to retry", COLOR_CRIMSON);
        return false;
    }

    // Serial dump for debugging
    Serial.println(F("========================================"));
    Serial.println(F("[ESP32] GOLDEN HOUR — TRIPLET FOCUS QUEUE"));
    Serial.printf("  Total in queue  : %d\n", totalInQueue);
    Serial.printf("  Tasks returned  : %d\n", count);
    Serial.println(F("  Tasks:"));
    for (JsonObject t : tasks) {
        Serial.printf("    [%d] %s (%s) id=%s\n",
                      t["index"] | 0,
                      t["title"] | "(no title)",
                      t["tasklist_title"] | "(no list)",
                      t["task_id"] | "(no id)");
    }
    Serial.println(F("========================================"));

    // Display top task
    const char* topTitle     = top["title"]     | "(no title)";
    const char* topListLabel = tasks[0]["tasklist_title"] | "(no list)";
    int topIndex             = top["index"] | 1;

    String ip = WiFi.localIP().toString();
    char ipBuf[20];
    ip.toCharArray(ipBuf, sizeof(ipBuf));

    drawTripletScreen(topTitle, topListLabel, topIndex, totalInQueue, ipBuf);
    return true;
}

// ============================================================================
// 7. SETUP
// ============================================================================

void setup() {
    setCpuFrequencyMhz(240);
    Serial.begin(115200);
    delay(200);

    Serial.println();
    Serial.println(F("**************************************************"));
    Serial.println(F("*  VGWD025K3 ~ CODEX OF TIME                    *"));
    Serial.println(F("*  Tab 2: GOLDEN HOUR — Cloudflare Tunnel POC   *"));
    Serial.println(F("**************************************************"));
    Serial.printf("[SYSTEM] CPU: %d MHz\n", getCpuFrequencyMhz());

    // Display init (HSPI)
    pinMode(PIN_TFT_CS, OUTPUT);
    digitalWrite(PIN_TFT_CS, HIGH);
    hspi.begin(PIN_LCD_SCK, -1, PIN_LCD_MOSI, PIN_TFT_CS);
    tft.begin();
    tft.setRotation(2);
    tft.fillScreen(COLOR_BG);
    Serial.println(F("[DISPLAY] GC9A01 online."));

    // ---- Wi-Fi + Backend ---------------------------------------------------
    if (!connectWiFi()) {
        Serial.println(F("[SYSTEM] HALT — Wi-Fi failed."));
        while (true) delay(1000);
    }

    if (!fetchAndDisplayTriplet()) {
        Serial.println(F("[SYSTEM] HALT — Backend fetch failed."));
        while (true) delay(1000);
    }

    Serial.println(F("[SYSTEM] Triplet displayed. Entering idle loop."));
}

// ============================================================================
// 8. LOOP — keep-alive RSSI logging; no interaction yet
// ============================================================================

void loop() {
    // Report RSSI every 10s so we can see link quality in Serial Monitor
    Serial.printf("[WIFI] Status: %s | RSSI: %d dBm\n",
                  WiFi.status() == WL_CONNECTED ? "CONNECTED" : "LOST",
                  WiFi.RSSI());
    delay(10000);
}

