// ============================================================================

SPIClass hspi(HSPI);
Adafruit_GC9A01A tft(&hspi, PIN_TFT_DC, PIN_TFT_CS, PIN_TFT_RST);

struct TaskItem {
    int index;
    String id;
    String listId;
    String listTitle;
    String title;
};

TaskItem triplet[3];
int tripletCount = 0;
