// ============================================================================
// 4. VIETNAMESE UTF-8 TO CLEAN ASCII NORMALIZER
// ============================================================================

/**
 * Converts Vietnamese diacritics into plain standard ASCII characters.
 * Prevents Adafruit_GFX from rendering deformed garbage glyphs for UTF-8 multi-bytes.
 */
String sanitizeVietnameseText(const String& input) {
    String result = "";
    size_t i = 0;
    size_t len = input.length();

    while (i < len) {
        uint8_t c = (uint8_t)input[i];

        if (c < 0x80) {
            // Standard 1-byte ASCII
            result += (char)c;
            i++;
        } else if (c == 0xC3) {
            // 2-byte UTF-8: 0xC3 series
            if (i + 1 < len) {
                uint8_t c2 = (uint8_t)input[i + 1];
                switch (c2) {
                    case 0x80: case 0x81: case 0x82: case 0x83: case 0x85: result += 'A'; break;
                    case 0xA0: case 0xA1: case 0xA2: case 0xA3: case 0xA5: result += 'a'; break;
                    case 0x88: case 0x89: case 0x8A: result += 'E'; break;
                    case 0xA8: case 0xA9: case 0xAA: result += 'e'; break;
                    case 0x8C: case 0x8D: result += 'I'; break;
                    case 0xAC: case 0xAD: result += 'i'; break;
                    case 0x92: case 0x93: case 0x94: case 0x95: result += 'O'; break;
                    case 0xB2: case 0xB3: case 0xB4: case 0xB5: result += 'o'; break;
                    case 0x99: case 0x9A: result += 'U'; break;
                    case 0xB9: case 0xBA: result += 'u'; break;
                    case 0x9D: result += 'Y'; break;
                    case 0xBD: result += 'y'; break;
                    default: result += '?'; break;
                }
                i += 2;
            } else {
                i++;
            }
        } else if (c == 0xC4 || c == 0xC5) {
            // 2-byte UTF-8: 0xC4 / 0xC5 series (Đ, đ, ă, â, ê, ô, ơ, ư)
            if (i + 1 < len) {
                uint8_t c2 = (uint8_t)input[i + 1];
                if (c == 0xC4) {
                    switch (c2) {
                        case 0x82: case 0x83: result += (c2 == 0x82) ? 'A' : 'a'; break;
                        case 0x90: case 0x91: result += (c2 == 0x90) ? 'D' : 'd'; break; // Đ / đ
                        case 0x98: case 0x99: result += (c2 == 0x98) ? 'E' : 'e'; break;
                        default: result += 'a'; break;
                    }
                } else { // 0xC5
                    switch (c2) {
                        case 0xA0: case 0xA1: result += (c2 == 0xA0) ? 'O' : 'o'; break; // Ơ / ơ
                        case 0xAF: case 0xB0: result += (c2 == 0xAF) ? 'U' : 'u'; break; // Ư / ư
                        default: result += 'u'; break;
                    }
                }
                i += 2;
            } else {
                i++;
            }
        } else if (c == 0xE1) {
            // 3-byte UTF-8: 0xE1 series (heavily used for tone marks: ả, ã, ạ, ắ, ằ, ẳ, ẵ, ặ, ấ, ầ, ẩ, ẫ, ậ, etc.)
            if (i + 2 < len) {
                uint8_t c2 = (uint8_t)input[i + 1];
                uint8_t c3 = (uint8_t)input[i + 2];

                if (c2 == 0xBA) {
                    if (c3 >= 0x80 && c3 <= 0x95) result += (c3 % 2 == 0) ? 'A' : 'a';
                    else if (c3 >= 0x96 && c3 <= 0xA9) result += (c3 % 2 == 0) ? 'E' : 'e';
                    else if (c3 >= 0xAA && c3 <= 0xB1) result += (c3 % 2 == 0) ? 'I' : 'i';
                    else if (c3 >= 0xB2 && c3 <= 0xBF) result += (c3 % 2 == 0) ? 'O' : 'o';
                    else result += 'a';
                } else if (c2 == 0xBB) {
                    if (c3 >= 0x80 && c3 <= 0x93) result += (c3 % 2 == 0) ? 'O' : 'o';
                    else if (c3 >= 0x94 && c3 <= 0xA3) result += (c3 % 2 == 0) ? 'U' : 'u';
                    else if (c3 >= 0xA4 && c3 <= 0xB1) result += (c3 % 2 == 0) ? 'Y' : 'y';
                    else result += 'o';
                } else {
                    result += ' ';
                }
                i += 3;
            } else {
                i++;
            }
        } else {
            // Skip unhandled multi-byte lead
            i++;
        }
    }
    return result;
}

