 */
void drawWrappedTaskTitle(const String& title, int16_t startY) {
    tft.setTextSize(2);
    tft.setTextColor(COLOR_TEXT_WHITE);

    int maxCharsPerLine = 16;
    int len = title.length();

    if (len <= 14) {
        // Single centered line
        int16_t tx = TFT_CENTER_X - (len * 12 / 2);
        tft.setCursor(max((int16_t)20, tx), startY + 8);
        tft.print(title);
    } else {
        // Multi-line wrap
        int start = 0;
        int line = 0;
        while (start < len && line < 3) {
            int chunkLen = min(maxCharsPerLine, len - start);

            // Try to split on space if not at end
            if (start + chunkLen < len) {
                int spaceIdx = title.lastIndexOf(' ', start + chunkLen);
                if (spaceIdx > start) {
                    chunkLen = spaceIdx - start;
                }
