/**
 * ============================================================================
 * VGWD025K3 ~ Codex of Time — Tab 2: Golden Hour (Task Engine)
 * Offline-First Triplet Cache + Vietnamese ASCII Normalization
 *
 * Objectives:
 *   1. Offline-First: Boots in < 2ms by loading cached tasks from LittleFS.
 *   2. Zero Wi-Fi on boot if cache exists. Only syncs when commanded or on cold start.
 *   3. Vietnamese Diacritics Filter: Converts multi-byte UTF-8 Vietnamese
 *      characters into clean, readable ASCII (e.g. "Nước" -> "Nuoc",
 *      "Giải bài" -> "Giai bai") so Adafruit_GFX displays crisp, legible text.
 *   4. Cloudflare Tunnel Sync: Fetches from https://faust.arc-system.id.vn
 *      and commits JSON to /triplet_cache.json on flash.
 *
 * Hardware: ESP32-WROOM-32 | GC9A01A 240x240 Round TFT (HSPI)
 * Architect: The Manager & Faust
 * Temporal Arc: Arc 3, 2026
 * ============================================================================
 */

#include <Arduino.h>
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_GC9A01A.h>
#include <WiFi.h>
#include <WiFiClientSecure.h>
#include <HTTPClient.h>
#include <ArduinoJson.h>
#include <LittleFS.h>

// ============================================================================
// 1. CONFIGURATION
// ============================================================================

#define WIFI_SSID        "Redmi K60 Ultra"
#define WIFI_PASSWORD    "toiyeufaust"
#define WIFI_TIMEOUT_MS  15000

// Cloudflare Tunnel base URL
#define BACKEND_HOST     "https://faust.arc-system.id.vn"
#define TRIPLET_ENDPOINT BACKEND_HOST "/api/v1/golden-hour/esp32/queue?limit=3"

// Flash storage
#define TRIPLET_CACHE_PATH "/triplet_cache.json"

// ============================================================================
// 2. HARDWARE PIN MATRIX (HSPI for GC9A01)
// ============================================================================

#define PIN_LCD_SCK      15   // HSPI Clock
#define PIN_LCD_MOSI      2   // HSPI MOSI
#define PIN_TFT_DC        4   // Data/Command
#define PIN_TFT_CS       16   // Chip Select
#define PIN_TFT_RST      17   // Hardware Reset

// Display geometry
#define TFT_CENTER_X    120
#define TFT_CENTER_Y    120

// Color palette
#define COLOR_BG        0x0000   // Pure Black
#define COLOR_HUD_RING  0x18E3   // Dark Tech Cyan
#define COLOR_CYAN_GLOW 0x07FF   // Bright Cyan
#define COLOR_GOLD      0xFDE0   // Gold Accent
#define COLOR_CRIMSON   0xF800   // Hazard / Error Red
#define COLOR_EMERALD   0x07E0   // Success Green
#define COLOR_TEXT_WHITE 0xFFFF  // Crisp White
#define COLOR_TEXT_MUTED 0x7BEF  // Dim Grey Text

// ============================================================================
// 3. GLOBAL OBJECTS & STRUCTS
// ============================================================================

SPIClass hspi(HSPI);
Adafruit_GC9A01A tft(&hspi, PIN_TFT_DC, PIN_TFT_CS, PIN_TFT_RST);

struct TaskItem {
    int index;
    String id;
    String listId;
    String listTitle;
    String title;
};

TaskItem triplet[3];
int tripletCount = 0;
int totalTasksInQueue = 0;
int selectedTaskIdx = 0;
String lastSyncTime = "OFFLINE";

// ============================================================================
// 4. VIETNAMESE UTF-8 TO CLEAN ASCII NORMALIZER
// ============================================================================

/**
 * Converts Vietnamese diacritics into plain standard ASCII characters.
 * Prevents Adafruit_GFX from rendering deformed garbage glyphs for UTF-8 multi-bytes.
 */
String sanitizeVietnameseText(const String& input) {
    String result = "";
    size_t i = 0;
    size_t len = input.length();

    while (i < len) {
        uint8_t c = (uint8_t)input[i];

        if (c < 0x80) {
            // Standard 1-byte ASCII
            result += (char)c;
            i++;
        } else if (c == 0xC3) {
            // 2-byte UTF-8: 0xC3 series
            if (i + 1 < len) {
                uint8_t c2 = (uint8_t)input[i + 1];
                switch (c2) {
                    case 0x80: case 0x81: case 0x82: case 0x83: case 0x85: result += 'A'; break;
                    case 0xA0: case 0xA1: case 0xA2: case 0xA3: case 0xA5: result += 'a'; break;
                    case 0x88: case 0x89: case 0x8A: result += 'E'; break;
                    case 0xA8: case 0xA9: case 0xAA: result += 'e'; break;
                    case 0x8C: case 0x8D: result += 'I'; break;
                    case 0xAC: case 0xAD: result += 'i'; break;
                    case 0x92: case 0x93: case 0x94: case 0x95: result += 'O'; break;
                    case 0xB2: case 0xB3: case 0xB4: case 0xB5: result += 'o'; break;
                    case 0x99: case 0x9A: result += 'U'; break;
                    case 0xB9: case 0xBA: result += 'u'; break;
                    case 0x9D: result += 'Y'; break;
                    case 0xBD: result += 'y'; break;
                    default: result += '?'; break;
                }
                i += 2;
            } else {
                i++;
            }
        } else if (c == 0xC4 || c == 0xC5) {
            // 2-byte UTF-8: 0xC4 / 0xC5 series (Đ, đ, ă, â, ê, ô, ơ, ư)
            if (i + 1 < len) {
                uint8_t c2 = (uint8_t)input[i + 1];
                if (c == 0xC4) {
                    switch (c2) {
                        case 0x82: case 0x83: result += (c2 == 0x82) ? 'A' : 'a'; break;
                        case 0x90: case 0x91: result += (c2 == 0x90) ? 'D' : 'd'; break; // Đ / đ
                        case 0x98: case 0x99: result += (c2 == 0x98) ? 'E' : 'e'; break;
                        default: result += 'a'; break;
                    }
                } else { // 0xC5
                    switch (c2) {
                        case 0xA0: case 0xA1: result += (c2 == 0xA0) ? 'O' : 'o'; break; // Ơ / ơ
                        case 0xAF: case 0xB0: result += (c2 == 0xAF) ? 'U' : 'u'; break; // Ư / ư
                        default: result += 'u'; break;
                    }
                }
                i += 2;
            } else {
                i++;
            }
        } else if (c == 0xE1) {
            // 3-byte UTF-8: 0xE1 series (heavily used for tone marks: ả, ã, ạ, ắ, ằ, ẳ, ẵ, ặ, ấ, ầ, ẩ, ẫ, ậ, etc.)
            if (i + 2 < len) {
                uint8_t c2 = (uint8_t)input[i + 1];
                uint8_t c3 = (uint8_t)input[i + 2];

                if (c2 == 0xBA) {
                    if (c3 >= 0x80 && c3 <= 0x95) result += (c3 % 2 == 0) ? 'A' : 'a';
                    else if (c3 >= 0x96 && c3 <= 0xA9) result += (c3 % 2 == 0) ? 'E' : 'e';
                    else if (c3 >= 0xAA && c3 <= 0xB1) result += (c3 % 2 == 0) ? 'I' : 'i';
                    else if (c3 >= 0xB2 && c3 <= 0xBF) result += (c3 % 2 == 0) ? 'O' : 'o';
                    else result += 'a';
                } else if (c2 == 0xBB) {
                    if (c3 >= 0x80 && c3 <= 0x93) result += (c3 % 2 == 0) ? 'O' : 'o';
                    else if (c3 >= 0x94 && c3 <= 0xA3) result += (c3 % 2 == 0) ? 'U' : 'u';
                    else if (c3 >= 0xA4 && c3 <= 0xB1) result += (c3 % 2 == 0) ? 'Y' : 'y';
                    else result += 'o';
                } else {
                    result += ' ';
                }
                i += 3;
            } else {
                i++;
            }
        } else {
            // Skip unhandled multi-byte lead
            i++;
        }
    }
    return result;
}

// ============================================================================
// 5. DISPLAY HELPERS (HIGH READABILITY & METRIC LAYOUT)
